// 机变 (SP draft) card content — server/sim/content/choices.js. Every family is driven end-to-end through the match
// harness in virtual time (the draft is generated by the match, cards are picked with g.choice, the effects land on
// the picker / teammates and reach the battles); battle-side parts are checked in the real sim (battle harness and
// real Battles inside the match).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeMatch, give, giveItem, chessOfTier, legalTileFor, checkInvariants as matchInvariants, DATA } from '../match/harness.js';
import { FakeBattle } from '../match/fakeBattle.js';
import { makeBattle, chessRec, enemyRec, checkInvariants } from '../helpers/battleHarness.js';
import { createRegistry } from '../../server/match/effectsMeta.js';
import { applyCard, generateDraft, tacticCard } from '../../server/match/choices.js';
import { withBounties } from '../../server/match/waves.js';
import { Battle } from '../../server/sim/Battle.js';
import { bountyOf, battlePlanOf, choiceCardIds, gateOf, hasBattlePart, mapAliases, BUILTIN_REFS } from '../../server/sim/content/choices.js';

const QUIET = { warn() {}, error() {}, info() {} };
const REG = createRegistry({ log: QUIET });
const EFF = (id) => DATA.effects[id];
const BAND = 'band_sarkazb'; // 歌利亚: no prep / battle effects of its own

/** Data copy whose SP round `round` of `modeId` always drafts `family`, optionally from a restricted card list. */
function dataWith(modeId, round, family, { tactic = null, bounty = null, cards = null, extra = {} } = {}) {
  const ch = DATA.choices;
  const sch = ch.schedule[modeId];
  const r = { ...sch.rounds[String(round)], families: [{ family, weight: 1 }], ...extra };
  if (cards) r.cards = cards;
  const out = { ...DATA, choices: { ...ch, schedule: { ...ch.schedule, [modeId]: { ...sch, rounds: { ...sch.rounds, [String(round)]: r } } }, cards: { ...ch.cards } } };
  if (tactic) out.choices.cards.tactic = ch.cards.tactic.filter((c) => tactic.includes(c.effectId));
  // the listed bounty cards are offered by this draft even when the real one would not (战术特训 comes from 法术教鞭
  // only — choices.json `draft`, user playtest #6 item 4; each card belongs to one kind of official draft —
  // `draftPool`, player feedback #2; a card without one fits every draft): these tests drive the payouts through the draft
  if (bounty) out.choices.cards.bounty = ch.cards.bounty.filter((c) => bounty.includes(c.effectId)).map(({ draftPool, ...c }) => ({ ...c, draft: true }));
  return out;
}

/** Drive the humans (info, band, ready) until the 机变 overlay of round r is open (no card picked yet). */
function toDraft(h, r) {
  const m = h.m;
  const ok = h.drive(() => m.phase === 'SP_DRAFT' && m.round === r, { band: BAND });
  assert.ok(ok, `no 机变 at R${r} (phase ${m.phase} R${m.round})`);
  return m.sp;
}

/**
 * Lay out the open 战术决策 as exactly the tactic cards `ids` (each its own index). The draft draws every card on its own,
 * with replacement (the official 补给 ×2), so a small test pool can repeat one card and miss another: the tests that
 * drive a card's effect through g.choice offer their cards this way, after checking what the generator drew.
 */
function offerTactic(m, ids) {
  m.sp.cards = ids.map((id, idx) => ({ ...tacticCard(DATA.choices.cards.tactic.find((c) => c.effectId === id)), idx, family: 'tactic' }));
  m.markPublic();
  return m.sp;
}

/** Pick cards in the draft's (random) order: plan = { playerId: cardId }; bots pick by themselves. */
function draftPicks(h, plan) {
  const m = h.m;
  for (let guard = 0; guard < 1000 && m.phase === 'SP_DRAFT'; guard++) {
    const pid = m.spTurn();
    const ps = pid ? m.players.get(pid) : null;
    if (!ps || ps.isBot || !(pid in plan)) { h.sched.runNext(); continue; }
    const want = plan[pid];
    const c = m.sp.cards.find((x) => m.sp.taken[x.idx] == null && (want == null || x.id === want));
    assert.ok(c, `${pid}: card ${want} not offered (${m.sp.cards.map((x) => x.id).join(', ')})`);
    assert.deepEqual(m.handle(pid, { t: 'g.choice', idx: c.idx }), { ok: true });
  }
  assert.equal(m.phase, 'PREP', '机变 → prep');
}

/** Ready every human and run until `pred` (combat included). */
const runTo = (h, pred) => assert.ok(h.drive(pred, { band: BAND }), `condition not reached (phase ${h.m.phase} R${h.m.round})`);

/** A ref-shaped playerEffects entry of a card (what the match sends to the battle). */
const refOf = (effectId, params = {}, id = `choice:${effectId}#1`) => ({ id, key: `choice:${effectId}`, source: 'choice', params, counter: null, data: { effectId } });

/** Every item a player owns: hand, temp and equipped on its chess. */
const ownedItems = (ps) => {
  const out = [];
  for (const p of [...ps.hand, ...ps.temp, ...ps.board.values()]) {
    if (!p) continue;
    if (p.kind === 'item') out.push(p);
    if (p.kind === 'chess') for (const it of p.items || []) out.push(it);
  }
  return out;
};

const guard = (o = {}) => chessRec({ id: 'test_guard', stats: { maxHp: 2000, atk: 500, def: 200, res: 0, respawnTime: 20 }, skill: null, ...o });

