// coverage & data

test('coverage: every 悬赏 / 战术决策 effect and every 道具补给 / 机密商店 item has a content choice: handler', () => {
  const ids = choiceCardIds(DATA);
  assert.equal(ids.bounty.length, 129, '129 ENEMY_GAIN effects');
  assert.equal(ids.tactic.length, 43, '43 BUFF_GAIN effects');
  // 56 normal EQUIP items − the 5 effect-only ones (4 special 维式重锤, 突变细胞: never sold, user playtest #4)
  assert.equal(ids.items.length, 51, '51 shop items');
  for (const id of ['chess_item_2_03_e_a', 'chess_item_3_09_e_a', 'chess_item_3_10_e_a', 'chess_item_4_09_e_a', 'chess_item_5_08_e_a']) assert.ok(!ids.items.includes(id), `${id} is never a supply card`);
  assert.ok(ids.items.includes('chess_item_1_01_e_a'), 'the plain 维式重锤 is');
  for (const id of [...ids.bounty, ...ids.tactic, ...ids.items]) {
    const h = REG.get(`choice:${id}`);
    assert.ok(h && typeof h.onChoicePick === 'function', `choice:${id}`);
  }
  // every card of choices.json is covered, every item the supply / shop families can draw too
  for (const c of DATA.choices.cards.bounty) assert.ok(ids.bounty.includes(c.effectId), c.effectId);
  for (const c of DATA.choices.cards.tactic) assert.ok(ids.tactic.includes(c.effectId), c.effectId);
  const m = makeMatch({ mode: 'coop', seed: 1, registry: REG, fake: true }).m;
  for (const t of [1, 2, 3, 4, 5, 6]) for (const id of m.gd.shopItemsByTier[t] || []) assert.ok(ids.items.includes(id), id);
  m.dispose();
  // team cards ("若存在其他队友则他们也获得") are exactly the icon_team_buff cards
  for (const c of DATA.choices.cards.tactic) {
    const e = EFF(c.effectId);
    assert.equal(c.team, e.decoIconId === 'icon_team_buff', `${c.effectId} team flag vs icon`);
    assert.equal(c.team, e.desc.includes('若存在其他队友'), `${c.effectId} team flag vs text`);
  }
  // every official 机变 event belongs to one of the four families
  for (const ev of Object.values(DATA.choices.events)) assert.ok(['bounty', 'supply', 'shop', 'tactic'].includes(ev.family), ev.id);
  // every buff key of a tactic card is understood (prep side or battle plan / device aliases)
  const known = new Set(['global_special_choice_gain_equip', 'global_special_choice_bond_addlayer', 'global_special_choice_gain_coin',
    'global_special_choice_refresh_free', 'single_special_choice_gloden_equip_chess', 'single_special_choice_gloden_char_chess',
    'single_special_choice_gain_bond_chess', 'auto_chess_change_map', 'global_special_choice_all_activated',
    'global_special_choice_prep_finish_bench_at_least', 'global_special_choice_prep_finish_bench_at_most',
    'global_special_choice_prep_finish_same_row_at_least', 'env_gbuff_new', 'env_gbuff_new_with_verify', 'char_respawntime_mul',
    'enemy_attribute_mul', 'enemy_attribute_add']);
  for (const id of ids.tactic) {
    const e = EFF(id);
    for (const b of e.buffs) assert.ok(known.has(b.key), `${id}: unknown buff key ${b.key}`);
    if (hasBattlePart(e)) assert.ok(battlePlanOf(refOf(id)) || Object.keys(mapAliases(e)).length, `${id}: battle part not implemented`);
  }
});

test('悬赏 data: the bounty read from each effect blackboard matches its card (count, coin, payout, rounds, enemy)', () => {
  let perfect = 0;
  for (const c of DATA.choices.cards.bounty) {
    const b = bountyOf(EFF(c.effectId), c);
    assert.ok(b, c.effectId);
    assert.ok(DATA.enemies[b.enemyKey], `${c.effectId}: enemy ${b.enemyKey}`);
    for (const k of ['enemyKey', 'count', 'coin', 'payout', 'rounds', 'tier']) assert.equal(b[k], c[k], `${c.effectId}.${k}`);
    assert.equal(b.coin, EFF(c.effectId).enemyPrice, `${c.effectId}: coins = enemyPrice`);
    if (b.payout === 'perfect') perfect++;
  }
  assert.equal(perfect, 20, '20 战术特训 (selfbattle_win) bounties');
  // enemyeffect_1 lists a stale next_battle_add_enemy_win_gain_coin (count 4) next to its add_enemy_* buff (count 3)
  const e1 = bountyOf(EFF('enemyeffect_1'));
  assert.equal(e1.count, 3, 'the text says 添加3只');
  assert.equal(e1.payout, 'perfect');
  assert.match(EFF('enemyeffect_1').desc, /添加3只/);
  // multi-round: 99 = every later battle
  assert.equal(bountyOf(EFF('enemyInitial_3')).rounds, 99);
  assert.equal(bountyOf(EFF('enemyeffect_2')).rounds, 99);
  assert.equal(bountyOf(EFF('enemyeffect_5_1')).coin, 0, '源石虫·特训 pays nothing');
});

// =====================================================================================================================
// 悬赏决策

const KILL = 'enemyeffect_3_4';   // 山海众头目·悬赏: 1 enemy, killer +2, next battle
const KILL2 = 'enemyeffect_12_4'; // 悬赏·损伤I: 1 enemy, killer +1, next 2 battles
const PERF = 'enemyeffect_11_1';  // 战术特训·频次I: 1 enemy, +1 when the own phase is perfect

test('悬赏决策 E2E (co-op, real battles): the picker\'s own battle gets the enemy; the killer earns the kill coins, 战术特训 pays a perfect own phase', () => {
  const data = dataWith('mode_multi_normal', 3, 'bounty', { bounty: [KILL, PERF] });
  const h = makeMatch({ mode: 'coop', difficulty: 'NORMAL', humans: 2, seed: 31, data, registry: REG });
  const m = h.m;
  // real battles where every enemy of a player is struck down by that player's operator the tick it appears
  const fields = [];
  m.BattleClass = class extends Battle {
    constructor(opts) {
      const user = opts.setup;
      super({ ...opts, setup: (b) => {
        if (typeof user === 'function') user(b);
        b.on('tick', () => {
          for (const e of b.enemies) {
            if (!e.alive || e.bossPool) continue;
            const op = b.allyUnits.find((u) => u.kind === 'op' && u.ownerId === e.ownerId && u.alive && u.deployed);
            if (op) b.kill(e, op);
          }
        });
      } });
      fields.push(this);
    }
  };
  h.start();
  const sp = toDraft(h, 3);
  assert.equal(sp.family, 'bounty');
  assert.equal(m.publicView().sp.name, '悬赏决策');
  assert.deepEqual(sp.cards.map((c) => c.id).sort(), [KILL, PERF].sort());
  for (const c of m.publicView().sp.cards) {
    const card = DATA.choices.cards.bounty.find((x) => x.effectId === c.id);
    assert.equal(c.kind, 'bounty');
    assert.deepEqual([c.coin, c.payout, c.rounds, c.enemyKey, c.count], [card.coin, card.payout, card.rounds, card.enemyKey, card.count]);
  }
  const [a, b] = sp.order;
  draftPicks(h, { [a]: KILL, [b]: PERF });
  const A = h.ps(a);
  const B = h.ps(b);
  assert.deepEqual(A.bounties.map((x) => x.card.effectId), [KILL], 'personal: only the picker');
  assert.deepEqual(B.bounties.map((x) => x.card.effectId), [PERF]);
  const kill = bountyOf(EFF(KILL));
  const perf = bountyOf(EFF(PERF));
  assert.ok(A.privateView().nextEnemies.some((e) => e.enemyKey === kill.enemyKey && e.tag === 'bounty' && e.count >= 1), 'preview');
  assert.ok(!B.privateView().nextEnemies.some((e) => e.enemyKey === kill.enemyKey && e.tag === 'bounty'));
  // an operator on each board (the killer)
  for (const ps of [A, B]) { const id = chessOfTier(1)[0]; give(m, ps, id, 'board', legalTileFor(m, ps, id)); }
  runTo(h, () => m.phase === 'ROUND_START' && m.round === 4);
  const r3 = fields.filter((f) => f.round === 3 && f.kind === 'normal');
  assert.equal(r3.length, 2);
  const fa = r3.find((f) => f.players[0].playerId === a);
  const fb = r3.find((f) => f.players[0].playerId === b);
  const ra = fa.result().perPlayer[a];
  const rb = fb.result().perPlayer[b];
  assert.ok(ra.perfect && rb.perfect, 'both own phases perfect');
  assert.equal(ra.coins, kill.coin, 'the killer (the picker\'s operator) earned the kill bounty');
  assert.equal(rb.coins, 0, '战术特训 enemies carry no kill bounty');
  // coins arrive at the next round start with the income (leftover funds were lost at prep end)
  assert.equal(A.funds, m.gd.income(4) + kill.coin);
  assert.equal(B.funds, m.gd.income(4) + perf.coin, 'perfect own phase ⇒ 战术特训 coins');
  assert.equal(A.bounties.length + B.bounties.length, 0, 'one-battle bounties expire');
  matchInvariants(m);
  m.dispose();
});

test('悬赏决策: multi-battle bounties persist for `rounds` battles; 战术特训 pays nothing when the own phase leaks', () => {
  const data = dataWith('mode_multi_normal', 3, 'bounty', { bounty: [KILL2, PERF] });
  let leaker = null;
  const h = makeMatch({ mode: 'coop', difficulty: 'NORMAL', humans: 2, seed: 32, data, registry: REG, fake: true,
    script: (bt) => (bt.kind === 'normal' && leaker && bt.players.includes(leaker) ? { leaks: { [leaker]: 1 } } : {}) });
  const m = h.m;
  h.start();
  const sp = toDraft(h, 3);
  const [a, b] = sp.order;
  leaker = b;
  draftPicks(h, { [a]: KILL2, [b]: PERF });
  const k2 = bountyOf(EFF(KILL2));
  assert.equal(k2.rounds, 2);
  runTo(h, () => m.phase === 'ROUND_START' && m.round === 4);
  const spawnsOf = (round, pid) => FakeBattle.instances.filter((f) => f.round === round && f.kind === 'normal' && f.players.includes(pid)).flatMap((f) => f.spawns);
  const bountyA3 = spawnsOf(3, a).filter((s) => s.tag === 'bounty');
  assert.equal(bountyA3.length, 1);
  assert.equal(bountyA3[0].enemyKey, k2.enemyKey);
  assert.equal(bountyA3[0].count, k2.count);
  assert.deepEqual(bountyA3[0].bounty, { coins: k2.coin, ownerPlayerId: a }, 'kill bounty → paid by the Battle to the killer');
  const bountyB3 = spawnsOf(3, b).filter((s) => s.tag === 'bounty');
  assert.equal(bountyB3.length, 1);
  assert.equal(bountyB3[0].bounty ?? null, null, '战术特训: no kill payout');
  assert.equal(h.ps(b).funds, m.gd.income(4), 'leaked ⇒ no 战术特训 coins');
  assert.equal(h.ps(a).bounties.length, 1, 'KILL2 still has one battle to go');
  runTo(h, () => m.phase === 'ROUND_START' && m.round === 5);
  assert.equal(spawnsOf(4, a).filter((s) => s.tag === 'bounty').length, 1, 'second battle');
  assert.equal(spawnsOf(4, b).filter((s) => s.tag === 'bounty').length, 0);
  assert.equal(h.ps(a).bounties.length, 0);
  m.dispose();
});

test('悬赏决策 (solo HARD R3): bounty enemies take the round\'s enemy scale only — no extra solo ×0.7 (research 08 §8 #8)', () => {
  const run = (mode, modeId, pickId) => {
    const data = dataWith(modeId, 3, 'bounty', { bounty: [KILL, PERF] });
    const h = makeMatch({ mode, difficulty: 'HARD', humans: 1, seed: 33, data, registry: REG, fake: true });
    h.start();
    toDraft(h, 3);
    draftPicks(h, { p_0: pickId });
    runTo(h, () => h.m.phase === 'ROUND_START' && h.m.round === 4);
    const spec = FakeBattle.instances.find((f) => f.round === 3 && f.kind === 'normal').spawns.find((s) => s.tag === 'bounty');
    const scale = h.m.gd.enemyScale(3);
    h.m.dispose();
    return { spec, scale };
  };
  // the official "所有敌人的生命值、攻击力降低至70%" of 独立模拟 is the global solo base already in enemyScale: a bounty
  // (战术特训 perfect or kill) spawns exactly like a wave enemy of the round, in solo and co-op alike, DEF untouched
  for (const [mode, modeId] of [['solo', 'mode_single_hard'], ['coop', 'mode_multi_hard']]) {
    for (const pick of [PERF, KILL]) {
      const { spec, scale } = run(mode, modeId, pick);
      const tag = `${mode} ${pick === PERF ? 'perfect' : 'kill'}`;
      assert.ok(Math.abs(spec.mods.hpMul - scale.hpMul) < 1e-9, `${tag}: hp ${spec.mods.hpMul} = scale ${scale.hpMul}`);
      assert.ok(Math.abs(spec.mods.atkMul - scale.atkMul) < 1e-9, `${tag}: atk`);
      assert.ok(spec.mods.defMul == null || spec.mods.defMul === 1, `${tag}: no DEF change`);
    }
  }
});

test('悬赏决策: the normal battle runs the client\'s spawn list — bounty units inserted into their host action, which is re-timed (waves.js withBounties)', () => {
  const data = dataWith('mode_single_hard', 3, 'bounty', { bounty: [KILL] });
  // seed 34: a ground R3 whose walker action 0 hosts the 山海众头目 (seed 33 is a FLY round: the bounty spawns alone)
  const h = makeMatch({ mode: 'solo', difficulty: 'HARD', humans: 1, seed: 34, data, registry: REG, fake: true });
  h.start();
  toDraft(h, 3);
  draftPicks(h, { p_0: KILL });
  const m = h.m;
  const ps = h.ps('p_0');
  assert.equal(ps.bounties.length, 1);
  const want = withBounties(m.gd, 3, m.wave, ps.bounties, 'p_0');
  const host = want.find((x) => x.tag === 'bounty').actionIndex;
  assert.ok(want.filter((x) => x.tag !== 'bounty' && x.actionIndex === host).length >= 1, 'fixture: the host action spawns units of its own');
  runTo(h, () => m.phase === 'COMBAT' && m.round === 3);
  const fb = FakeBattle.instances.find((f) => f.round === 3 && f.kind === 'normal');
  const view = (list) => list.map((x) => [x.enemyKey, +x.time.toFixed(9), x.count, +(x.interval || 0).toFixed(9), x.tag ?? null, x.actionIndex ?? null]);
  assert.deepEqual(view(fb.spawns), view(want), 'same specs, times and spacing as withBounties');
  assert.ok(fb.spawns.every((x) => x.ownerPlayerId === 'p_0'));
  // the preview keeps one entry per action (the host action is not split there)
  const pv = m.nextEnemiesFor(ps);
  assert.equal(pv.reduce((n, e) => n + e.count, 0), want.reduce((n, x) => n + x.count, 0), 'same enemy total');
  m.dispose();
});

test('悬赏 kill payout in the real sim: a 联防 helper that strikes down a leaked bounty enemy takes the coins', () => {
  const kill = bountyOf(EFF(KILL));
  const players = [
    { playerId: 'p1', seat: 0, side: 'L', colOffset: 0, units: [{ uid: 1, kind: 'chess', chessId: 'test_guard', row: 10, col: 4 }], bonds: {} },
    { playerId: 'p2', seat: 1, side: 'L', colOffset: 8, units: [{ uid: 2, kind: 'chess', chessId: 'test_guard', row: 10, col: 4 }], bonds: {} },
  ];
  const h = makeBattle({ kind: 'unite', defs: { chess: { test_guard: guard() }, enemies: { enemy_b: enemyRec({ key: 'enemy_b', hp: 1000, speed: 0 }) } }, players, autoFinish: false, timeLimit: 30 });
  h.step();
  const e = h.spawn('enemy_b', { pos: [11, 14], ownerPlayerId: 'p2', sourcePlayerId: 'p1', bounty: { coins: kill.coin, ownerPlayerId: 'p1' } });
  const helper = h.b.allyUnits.find((u) => u.ownerId === 'p2' && u.kind === 'op');
  h.b.dealDamage(helper, e, h.b.makeDamage({ amount: 1e6, type: 'true' }));
  assert.equal(e.alive, false);
  const r = h.b.result();
  assert.equal(r.perPlayer.p2.coins, kill.coin, 'the killer (helper) is paid');
  assert.equal(r.perPlayer.p1.coins, 0);
  checkInvariants(h.b);
});

