// 道具补给 / 机密商店

test('道具补给 E2E (co-op): 6 free normal items within the round window; the pick lands in the picker\'s hand (temp when full)', () => {
  const data = dataWith('mode_multi_normal', 3, 'supply');
  const h = makeMatch({ mode: 'coop', difficulty: 'NORMAL', humans: 2, seed: 41, data, registry: REG, fake: true });
  const m = h.m;
  h.start();
  const sp = toDraft(h, 3);
  assert.equal(sp.family, 'supply');
  assert.equal(m.publicView().sp.name, '道具补给');
  const [lo, hi] = data.choices.schedule.mode_multi_normal.rounds['3'].supplyTiers;
  assert.equal(sp.cards.length, 6);
  for (const c of m.publicView().sp.cards) {
    const it = DATA.items[c.id];
    assert.equal(c.kind, 'item');
    assert.equal(c.price, 0, '无需消耗资金');
    assert.ok(it && !it.isGolden && it.itemType === 'EQUIP' && it.tier >= lo && it.tier <= hi, `${c.id} tier ${it && it.tier}`);
  }
  const [a, b] = sp.order;
  const A = h.ps(a);
  const B = h.ps(b);
  // B's regular hand is full (10 different operators): the item overflows into the temporary slots
  const fillers = chessOfTier(1).concat(chessOfTier(2));
  for (let i = 0; i < B.hand.length; i++) if (!B.hand[i]) give(m, B, fillers[i], 'hand', i);
  const fundsA = A.funds;
  const fundsB = B.funds;
  const cardA = sp.cards[0].id;
  const cardB = sp.cards[1].id;
  draftPicks(h, { [a]: cardA, [b]: cardB });
  const owns = (ps, id) => [...ps.hand, ...ps.temp].some((p) => p && (p.id === id || p.id === DATA.items[id].goldenId));
  assert.ok(owns(A, cardA), 'picker A got its item');
  assert.ok(owns(B, cardB), 'picker B got its item');
  assert.ok(B.temp.some((p) => p && (p.id === cardB || p.id === DATA.items[cardB].goldenId)), 'full hand → temp');
  assert.equal(A.funds, fundsA, 'free');
  assert.equal(B.funds, fundsB, 'free');
  assert.ok(!owns(A, cardB) || cardA === cardB, 'items are personal');
  matchInvariants(m);
  m.dispose();
});

