const TEAM_PREP = ['allybuff_select_1', 'allybuff_select_2_2', 'allybuff_select_3', 'allybuff_select_4', 'allybuff_select_5', 'allybuff_select_7_1'];

test('战术决策 E2E (co-op 3): team cards reach every teammate (AI included), personal cards only the picker', () => {
  const data = dataWith('mode_multi_normal', 3, 'tactic', { tactic: TEAM_PREP });
  const h = makeMatch({ mode: 'coop', difficulty: 'NORMAL', humans: 2, bots: 1, seed: 51, data, registry: REG, fake: true });
  const m = h.m;
  h.start();
  const sp = toDraft(h, 3);
  assert.equal(sp.family, 'tactic');
  assert.equal(m.publicView().sp.name, '战术决策');
  assert.equal(m.publicView().sp.desc, '进行协同调整，做好迎战准备。', 'the official header');
  assert.equal(sp.cards.length, 6);
  assert.ok(sp.cards.every((c) => TEAM_PREP.includes(c.id)), 'drawn from the pool (with replacement)');
  offerTactic(m, TEAM_PREP);
  const view = m.publicView().sp.cards;
  for (const c of view) assert.equal(c.team, DATA.choices.cards.tactic.find((x) => x.effectId === c.id).team, `${c.id} team flag`);
  const all = [...m.players.values()];
  const before = new Map(all.map((ps) => [ps.playerId, { funds: ps.funds, free: ps.shop.freeRefreshes, yan: ps.layers.yanShip || 0, invest: ps.layers.investShip || 0,
    items: new Set(ownedItems(ps).map((p) => p.uid)), chess: [...ps.hand, ...ps.temp].filter((p) => p && p.kind === 'chess').length }]));
  // the humans take 列装 (team) and 整备 (personal); the AI picks what it likes
  draftPicks(h, { p_0: 'allybuff_select_1', p_1: 'allybuff_select_5' });
  const aiIdx = sp.picks.ai_0;
  const aiCard = aiIdx != null ? sp.cards[aiIdx].id : null;
  assert.ok(aiCard && !['allybuff_select_1', 'allybuff_select_5'].includes(aiCard), 'the AI took one of the other cards');
  const itemsOf = ownedItems;
  // 列装: 2 random tier-I items for everyone (pool_equip_shop_1)
  for (const ps of all) {
    const had = before.get(ps.playerId).items;
    const now = new Set(itemsOf(ps).map((p) => p.uid));
    const fresh = itemsOf(ps).filter((p) => !had.has(p.uid));
    // an identical normal pair merges into the 进阶 item (counts 2); an owned copy consumed by a merge counts −1
    const n = fresh.reduce((k, p) => k + (DATA.items[p.id].isGolden ? 2 : 1), 0) - [...had].filter((u) => !now.has(u)).length;
    assert.equal(n, 2, `${ps.playerId}: 列装 gives 2 items`);
    for (const it of fresh) assert.equal(DATA.items[it.id].tier, 1, `${ps.playerId}: tier-I item ${it.id}`);
  }
  // 整备: personal EffectRef on p_1 only
  assert.ok(h.ps('p_1').effects.some((e) => e.key === BUILTIN_REFS.goldenItem && e.counter === 1));
  assert.ok(!h.ps('p_0').effects.some((e) => e.key === BUILTIN_REFS.goldenItem));
  // the AI's card, whatever it was, followed its team flag
  {
    const team = DATA.choices.cards.tactic.find((c) => c.effectId === aiCard).team;
    const check = {
      allybuff_select_2_2: (ps) => (ps.layers.yanShip || 0) - before.get(ps.playerId).yan === 10 && (ps.layers.investShip || 0) - before.get(ps.playerId).invest === 10,
      allybuff_select_3: (ps) => ps.funds - before.get(ps.playerId).funds === 1,
      allybuff_select_4: (ps) => ps.shop.freeRefreshes - before.get(ps.playerId).free === 2,
      allybuff_select_7_1: (ps) => [...ps.hand, ...ps.temp].filter((p) => p && p.kind === 'chess').length - before.get(ps.playerId).chess === 1,
    }[aiCard];
    if (check) for (const ps of all) assert.equal(check(ps), team || ps.playerId === 'ai_0', `${aiCard} on ${ps.playerId}`);
  }
  matchInvariants(m);
  m.dispose();
});

test('战术决策 prep cards through the handlers: 盟誓 layers (无需激活), 财富, 补给, 驰援 (bond chess ≤ shop level)', () => {
  const h = makeMatch({ mode: 'coop', humans: 2, seed: 52, registry: REG, fake: true }).start();
  h.toPrep(1, { band: BAND });
  const m = h.m;
  const [a, b] = [h.ps('p_0'), h.ps('p_1')];
  const tactic = (id) => ({ kind: 'tactic', id, name: EFF(id).name, desc: EFF(id).desc, team: !!DATA.choices.cards.tactic.find((c) => c.effectId === id)?.team, tacticKind: 'ally', family: 'tactic', idx: 0 });
  for (const id of ['allybuff_select_2_1', 'allybuff_select_2_2', 'allybuff_select_2_3', 'allybuff_select_2_4', 'allybuff_select_2_5', 'allybuff_select_2_6', 'allybuff_select_2_7', 'allybuff_select_2_8']) {
    const buff = EFF(id).buffs[0];
    const bonds = buff.bbStr.bond_list.split(',');
    const la = bonds.map((x) => a.layers[x] || 0);
    const lb = bonds.map((x) => b.layers[x] || 0);
    applyCard(m, a, tactic(id));
    bonds.forEach((x, i) => {
      assert.equal((a.layers[x] || 0) - la[i], buff.bb.count, `${id} ${x} picker`);
      assert.equal((b.layers[x] || 0) - lb[i], buff.bb.count, `${id} ${x} teammate`);
    });
  }
  const fa = a.funds;
  const fb = b.funds;
  applyCard(m, b, tactic('allybuff_select_3'));
  assert.deepEqual([a.funds - fa, b.funds - fb], [1, 1], '财富 +1 each');
  applyCard(m, b, tactic('allybuff_select_4'));
  applyCard(m, a, tactic('allybuff_select_4'));
  assert.deepEqual([a.shop.freeRefreshes, b.shop.freeRefreshes], [4, 4], '补给 stacks');
  // 驰援: one random chess of the bond, personal
  for (const id of ['allybuff_select_7_1', 'allybuff_select_7_2', 'allybuff_select_7_3', 'allybuff_select_7_4', 'allybuff_select_7_5', 'allybuff_select_7_6', 'allybuff_select_7_7', 'allybuff_select_7_8']) {
    const bond = EFF(id).buffs[0].bbStr.bond;
    const chessOf = (ps) => [...ps.hand, ...ps.temp, ...ps.board.values()].filter((p) => p && p.kind === 'chess').map((p) => p.uid);
    const nb = chessOf(b).length;
    // clear A's chess first (pool copies go back) so the grant is the only one
    for (const uid of chessOf(a)) { const l = a.find(uid); if (l) { a._detach(l); a.removeTokensOf(uid); a.returnCopies(l.piece); } }
    a.recompute();
    applyCard(m, a, tactic(id));
    const got = [...a.hand, ...a.temp].filter((p) => p && p.kind === 'chess');
    assert.equal(got.length, 1, `${id}: one chess`);
    const rec = DATA.chess[got[0].id];
    assert.ok(rec.bonds.includes(bond), `${id}: ${rec.name} belongs to ${bond}`);
    const lowExists = Object.values(DATA.chess).some((c) => c.visible && !c.isGolden && c.bonds.includes(bond) && c.tier <= a.shop.level && m.pool.has(c.chessId));
    if (lowExists) assert.ok(rec.tier <= a.shop.level, `${id}: tier ${rec.tier} ≤ shop level ${a.shop.level}`);
    assert.equal(chessOf(b).length, nb, `${id} is personal`);
  }
  matchInvariants(m);
  m.dispose();
});

test('战术决策 升华 / 整备: the next purchased operator becomes elite, the next purchased item 进阶 (one use each)', () => {
  const data = dataWith('mode_single_normal', 9, 'tactic', { tactic: ['allybuff_select_5', 'allybuff_select_6', 'allybuff_select_3'] });
  const h = makeMatch({ mode: 'solo', difficulty: 'NORMAL', humans: 1, seed: 53, data, registry: REG, fake: true });
  const m = h.m;
  h.start();
  toDraft(h, 9);
  offerTactic(m, ['allybuff_select_5', 'allybuff_select_6', 'allybuff_select_3']);
  draftPicks(h, { p_0: 'allybuff_select_6' });
  const ps = h.ps('p_0');
  const ref = ps.effects.find((e) => e.key === BUILTIN_REFS.eliteChess);
  assert.ok(ref && ref.counter === 1 && ref.iconId === EFF('allybuff_select_6').decoIconId);
  assert.ok(ps.effectsView().some((e) => e.id === ref.id && e.name === '升华'));
  ps.funds = 50;
  // wipe the hand through the pool accounting (draft picks may have granted pooled items)
  ps.hand.forEach((p) => { if (p) { for (const it of p.items || []) ps.returnCopies(it); ps.returnCopies(p); } });
  ps.hand.fill(null);
  ps.recompute();
  const slot = ps.shop.slots.findIndex((s) => s && s.kind === 'chess' && m.pool.left(m.gd.baseIdOf(s.id)) >= 3 && !ps.completesChessMerge(s.id));
  assert.ok(slot >= 0);
  const id = ps.shop.slots[slot].id;
  assert.deepEqual(m.handle('p_0', { t: 'g.buy', slot }), { ok: true });
  assert.ok(ps.hand.some((p) => p && p.id === DATA.chess[id].goldenId), '升华: elite');
  assert.ok(!ps.effects.some((e) => e.key === BUILTIN_REFS.eliteChess), 'consumed');
  const slot2 = ps.shop.slots.findIndex((s, i) => i !== slot && s && s.kind === 'chess' && !s.sold && !ps.completesChessMerge(s.id));
  if (slot2 >= 0) {
    const id2 = ps.shop.slots[slot2].id;
    m.handle('p_0', { t: 'g.buy', slot: slot2 });
    assert.ok(ps.hand.some((p) => p && p.id === id2), 'the next purchase stays normal');
  }
  // 整备 via its handler (same draft family on another pick)
  applyCard(m, ps, { kind: 'tactic', id: 'allybuff_select_5', name: '整备', desc: '', team: false, family: 'tactic', idx: 0 });
  const islot = ps.shop.slots.findIndex((s) => s && s.kind === 'item' && !s.sold);
  if (islot >= 0) {
    const iid = ps.shop.slots[islot].id;
    ps.funds = 50;
    assert.deepEqual(m.handle('p_0', { t: 'g.buy', slot: islot }), { ok: true });
    assert.ok([...ps.hand, ...ps.temp].some((p) => p && p.id === DATA.items[iid].goldenId), '整备: 进阶 item');
    assert.ok(!ps.effects.some((e) => e.key === BUILTIN_REFS.goldenItem), 'consumed');
  }
  matchInvariants(m);
  m.dispose();
});

