test('战术决策 E2E: 火力 / 锐利 evaluate the 手牌区 at every prep end; the battle input carries the result', () => {
  const data = dataWith('mode_multi_normal', 3, 'tactic', { tactic: ['allybuff_select_13', 'allybuff_select_19'] });
  const h = makeMatch({ mode: 'coop', difficulty: 'NORMAL', humans: 2, seed: 61, data, registry: REG, fake: true });
  const m = h.m;
  h.start();
  const sp = toDraft(h, 3);
  offerTactic(m, ['allybuff_select_13', 'allybuff_select_19']);
  const [a, b] = sp.order;
  draftPicks(h, { [a]: 'allybuff_select_13', [b]: 'allybuff_select_19' });
  const A = h.ps(a);
  const B = h.ps(b);
  for (const ps of [A, B]) {
    for (const id of ['allybuff_select_13', 'allybuff_select_19']) {
      const ref = ps.effects.find((e) => e.key === `choice:${id}`);
      assert.ok(ref && ref.battle && ref.iconKind === 'team' && ref.iconId === 'icon_team_buff', `${ps.playerId} ${id} (team card)`);
    }
  }
  // A keeps 3 cards in the 手牌区, B an empty one
  for (let i = 0; i < 3; i++) giveItem(m, A, 'chess_item_1_02_e_a');
  A.hand.fill(null);
  giveItem(m, A, 'chess_item_1_01_e_a');
  giveItem(m, A, 'chess_item_1_02_e_a');
  giveItem(m, A, 'chess_item_1_05_e_a');
  B.hand.fill(null);
  B.recompute();
  runTo(h, () => m.phase === 'ROUND_START' && m.round === 4);
  const inputOf = (round, pid) => FakeBattle.instances.find((f) => f.round === round && f.kind === 'normal' && f.players.includes(pid)).opts.players[0];
  const okOf = (input, id) => input.playerEffects.find((e) => e.key === `choice:${id}`).params.prepOk;
  assert.equal(okOf(inputOf(3, a), 'allybuff_select_13'), true, 'A: ≥ 3 cards ⇒ 火力 on');
  assert.equal(okOf(inputOf(3, a), 'allybuff_select_19'), false, 'A: 锐利 off');
  assert.equal(okOf(inputOf(3, b), 'allybuff_select_13'), false, 'B: 火力 off');
  assert.equal(okOf(inputOf(3, b), 'allybuff_select_19'), true, 'B: empty ⇒ 锐利 on');
  // the next prep end re-evaluates: B now holds 3 cards
  runTo(h, () => m.phase === 'PREP' && m.round === 4);
  for (const id of ['chess_item_1_01_e_a', 'chess_item_1_02_e_a', 'chess_item_1_05_e_a']) giveItem(m, B, id);
  runTo(h, () => m.phase === 'ROUND_START' && m.round === 5);
  assert.equal(okOf(inputOf(4, b), 'allybuff_select_13'), true, 'B R4: 火力 on');
  assert.equal(okOf(inputOf(4, b), 'allybuff_select_19'), false, 'B R4: 锐利 off');
  // those inputs, fought in the real sim
  const real = (input) => {
    const players = [{ ...input, units: [{ uid: 1, kind: 'chess', chessId: 'test_guard', row: 10, col: 4 }] }];
    const hb = makeBattle({ defs: { chess: { test_guard: guard() } }, players, autoFinish: false, timeLimit: 10 });
    hb.step();
    const u = hb.b.allyUnits.find((x) => x.kind === 'op');
    return { res: u.s.resIgnoreFlat, def: u.s.defIgnorePct };
  };
  assert.deepEqual(real(inputOf(3, a)), { res: EFF('allybuff_select_13').params.magic_resist_penetrate_fixed, def: 0 });
  assert.deepEqual(real(inputOf(3, b)), { res: 0, def: EFF('allybuff_select_19').params.def_penetrate });
  matchInvariants(m);
  m.dispose();
});

test('战术决策 E2E (real battles): 排斥 debuffs every enemy of the picker\'s own field, not the teammate\'s', () => {
  const id = 'enemydebuff_select_1';
  const data = dataWith('mode_multi_normal', 3, 'tactic', { tactic: [id, 'allybuff_select_3'] });
  const h = makeMatch({ mode: 'coop', difficulty: 'NORMAL', humans: 2, seed: 62, data, registry: REG });
  const m = h.m;
  const seen = [];
  m.BattleClass = class extends Battle {
    constructor(opts) {
      const user = opts.setup;
      super({ ...opts, setup: (b) => {
        if (typeof user === 'function') user(b);
        b.on('enemySpawn', ({ enemy }) => seen.push({ round: b.round, owner: enemy.ownerId, debuffed: enemy.buffs.some((x) => String(x.key).startsWith(`choice:${id}#`)), mul: enemy.s.atk / (enemy.base.atk || 1) }), { priority: -100 });
      } });
    }
  };
  h.start();
  const sp = toDraft(h, 3);
  offerTactic(m, [id, 'allybuff_select_3']);
  const [a, b] = sp.order;
  draftPicks(h, { [a]: id, [b]: 'allybuff_select_3' });
  assert.ok(h.ps(a).effects.some((e) => e.key === `choice:${id}` && e.iconId === 'icon_enemy_debuff'));
  assert.ok(!h.ps(b).effects.some((e) => e.key === `choice:${id}`), 'personal card');
  runTo(h, () => m.phase === 'ROUND_START' && m.round === 4);
  const r3 = seen.filter((s) => s.round === 3);
  assert.ok(r3.some((s) => s.owner === a) && r3.some((s) => s.owner === b));
  for (const s of r3) assert.equal(s.debuffed, s.owner === a, `enemy of ${s.owner}`);
  m.dispose();
});

test('自愈 (real sim): every damage instance an own unit takes heals 50; not HP loss, not under 禁疗, not the partner\'s units', () => {
  const val = EFF('allybuff_select_11').buffs[1].bb.value;
  const players = [
    { playerId: 'p1', seat: 0, side: 'L', colOffset: 0, units: [{ uid: 1, kind: 'chess', chessId: 'test_guard', row: 10, col: 4 }], bonds: {}, playerEffects: [refOf('allybuff_select_11')] },
    { playerId: 'p2', seat: 1, side: 'L', colOffset: 8, units: [{ uid: 2, kind: 'chess', chessId: 'test_guard', row: 10, col: 4 }], bonds: {} },
  ];
  const h = makeBattle({ kind: 'unite', defs: { chess: { test_guard: guard() } }, players, autoFinish: false, timeLimit: 30 });
  h.step();
  const u1 = h.b.allyUnits.find((u) => u.ownerId === 'p1' && u.kind === 'op');
  const u2 = h.b.allyUnits.find((u) => u.ownerId === 'p2' && u.kind === 'op');
  const hit = (u, amount, type = 'true') => h.b.dealDamage(null, u, h.b.makeDamage({ amount, type }));
  hit(u1, 300);
  assert.equal(u1.hp, 2000 - 300 + val);
  hit(u1, 100, 'phys');
  const afterPhys = u1.hp;
  assert.ok(afterPhys > 2000 - 300 + val - 100, 'healed after a physical hit too');
  h.b.loseHp(u1, 200);
  assert.equal(u1.hp, afterPhys - 200, 'HP loss (流失) is not damage');
  h.b.applyStatus(u1, 'noHeal', { duration: 5, force: true });
  hit(u1, 100);
  assert.equal(u1.hp, afterPhys - 300, '禁疗');
  hit(u2, 300);
  assert.equal(u2.hp, 1700, 'the partner has no 自愈');
  // summons are 我方单位 too (纸偶) — but not one that holds 禁疗 (沙之碑, PRTS 备注 "持有禁疗"; tokens.json abnormal)
  const tok = h.b.spawnToken(u1, 'token_10022_kazema_shadow', 11, 4, { stats: { maxHp: 1000 } });
  assert.ok(tok, 'summon placed');
  const before = tok.hp;
  hit(tok, 200);
  assert.equal(tok.hp, before - 200 + val, 'summon healed');
  const ob = h.b.spawnToken(u1, 'token_10011_beewax_oblisk', 12, 4, { stats: { maxHp: 1000 } });
  assert.ok(ob, '沙之碑 placed');
  const ob0 = ob.hp;
  hit(ob, 200);
  assert.equal(ob.hp, ob0 - 200, '沙之碑 (禁疗) not healed');
  checkInvariants(h.b);
});

test('无瑕 (real sim): operators at full HP get ATK / DEF ×1.3, lost on damage, back once healed to full', () => {
  const bb = EFF('allybuff_select_18').buffs[1].bb;
  const h = makeBattle({ defs: { chess: { test_guard: guard() } }, units: [{ chessId: 'test_guard', row: 10, col: 4 }], playerEffects: [refOf('allybuff_select_18')], autoFinish: false, timeLimit: 30 });
  h.step();
  const u = h.unit('test_guard');
  assert.ok(Math.abs(u.s.atk - 500 * (1 + bb.atk)) < 1e-6, `atk ${u.s.atk}`);
  assert.ok(Math.abs(u.s.def - 200 * (1 + bb.def)) < 1e-6, `def ${u.s.def}`);
  h.b.dealDamage(null, u, h.b.makeDamage({ amount: 100, type: 'true' }));
  assert.equal(u.s.atk, 500, 'not full ⇒ off at once');
  assert.equal(u.s.def, 200);
  h.b.heal(null, u, 1000);
  h.step();
  assert.ok(Math.abs(u.s.atk - 650) < 1e-6, 'full again');
  checkInvariants(h.b);
});

test('征召 (real sim): a row with 3 of the player\'s operators at battle start ⇒ redeploy time ×0.5; otherwise nothing', () => {
  const scale = EFF('allybuff_select_14').buffs[1].bb.scale;
  const run = (rows) => {
    const h = makeBattle({ defs: { chess: { test_guard: guard() } }, units: rows.map(([r, c], i) => ({ uid: i + 1, chessId: 'test_guard', row: r, col: c })),
      playerEffects: [refOf('allybuff_select_14')], autoFinish: false, timeLimit: 60 });
    h.step();
    return h;
  };
  const on = run([[10, 3], [10, 4], [10, 5]]);
  const u = on.b.allyUnits.find((x) => x.kind === 'op');
  assert.equal(u.s.redeployMul, scale);
  on.b.dealDamage(null, u, on.b.makeDamage({ amount: 1e6, type: 'true' }));
  assert.equal(u.alive, false);
  assert.ok(Math.abs(u.respawnAt - on.b.time - 20 * scale) < 1e-6, 'respawn after 10 s instead of 20 s');
  checkInvariants(on.b);
  const off = run([[10, 3], [10, 4], [11, 5]]);
  for (const x of off.b.allyUnits.filter((y) => y.kind === 'op')) assert.equal(x.s.redeployMul, 1);
});

test('火力 / 锐利 (real sim): the penetration applies only when the prep condition held; it really lowers the target\'s RES / DEF', () => {
  const enemies = { enemy_t: enemyRec({ key: 'enemy_t', hp: 1e7, def: 500, res: 20, speed: 0 }) };
  const run = (refs, info = null) => {
    const players = [{ playerId: 'p1', seat: 0, side: 'L', colOffset: 0, units: [{ uid: 1, kind: 'chess', chessId: 'test_guard', row: 10, col: 4 }], bonds: {}, playerEffects: refs, ...(info ? { contentInfo: info } : {}) }];
    const h = makeBattle({ defs: { chess: { test_guard: guard() }, enemies }, players, autoFinish: false, timeLimit: 30 });
    h.step();
    const u = h.b.allyUnits.find((x) => x.kind === 'op');
    const e = h.spawn('enemy_t', { pos: [10, 8] });
    const arts = h.b.dealDamage(u, e, h.b.makeDamage({ amount: 1000, type: 'arts' }));
    const phys = h.b.dealDamage(u, e, h.b.makeDamage({ amount: 1000, type: 'phys' }));
    return { arts, phys };
  };
  const none = run([]);
  assert.equal(Math.round(none.arts), 800);
  assert.equal(Math.round(none.phys), 500);
  const fire = run([refOf('allybuff_select_13', { prepOk: true })]);
  assert.equal(Math.round(fire.arts), 1000, 'RES 20 ignored');
  assert.equal(Math.round(run([refOf('allybuff_select_13', { prepOk: false })]).arts), 800, 'condition failed');
  const sharp = run([refOf('allybuff_select_19', { prepOk: true })]);
  assert.equal(Math.round(sharp.phys), 1000 - 500 * 0.7, '30 % of DEF ignored');
  // without the match's flag the battle falls back on contentInfo (hand count at battle start)
  assert.equal(Math.round(run([refOf('allybuff_select_13')], { handUnits: 3 }).arts), 1000);
  assert.equal(Math.round(run([refOf('allybuff_select_13')], { handUnits: 2 }).arts), 800);
});

test('排斥 / 责罚 / 裁决 (real sim): all / ELITE / BOSS enemies of the owner\'s half, blackboard numbers', () => {
  const enemies = {
    e_n: enemyRec({ key: 'e_n', rank: 'NORMAL', hp: 1e6, atk: 1000, def: 400, res: 20, speed: 0 }),
    e_e: enemyRec({ key: 'e_e', rank: 'ELITE', hp: 1e6, atk: 1000, def: 400, res: 20, speed: 0 }),
    e_b: enemyRec({ key: 'e_b', rank: 'BOSS', hp: 1e6, atk: 1000, def: 400, res: 20, speed: 0 }),
  };
  for (let k = 1; k <= 9; k++) {
    const id = `enemydebuff_select_${k}`;
    const buff = EFF(id).buffs[1];
    const rank = buff.bbStr.enemy_level_type ?? null;
    const players = [
      { playerId: 'p1', seat: 0, side: 'L', colOffset: 0, units: [], bonds: {}, playerEffects: [refOf(id)] },
      { playerId: 'p2', seat: 1, side: 'L', colOffset: 8, units: [], bonds: {} },
    ];
    const h = makeBattle({ kind: 'unite', defs: { enemies }, players, autoFinish: false, timeLimit: 30 });
    h.step();
    for (const key of ['e_n', 'e_e', 'e_b']) {
      for (const owner of ['p1', 'p2']) {
        const e = h.spawn(key, { pos: [10, owner === 'p1' ? 6 : 14], ownerPlayerId: owner });
        const hit = owner === 'p1' && (!rank || enemies[key].rank === rank);
        const exp = { atk: 1000, def: 400, res: 20 };
        if (hit) {
          if (buff.key === 'enemy_attribute_mul') exp.atk = 1000 * buff.bb.atk;
          if (buff.bb.def != null) exp.def = 400 + buff.bb.def;
          if (buff.bb.magic_resistance != null) exp.res = 20 + buff.bb.magic_resistance;
        }
        assert.ok(Math.abs(e.s.atk - exp.atk) < 1e-6 && Math.abs(e.s.def - exp.def) < 1e-6 && Math.abs(e.s.res - exp.res) < 1e-6,
          `${id} ${key} of ${owner}: ${e.s.atk}/${e.s.def}/${e.s.res} vs ${JSON.stringify(exp)}`);
      }
    }
    checkInvariants(h.b);
  }
});

test('模拟战场演变 E2E (act1 m01): the card clears the picker\'s crates for deployment and in battle, never a teammate\'s', () => {
  const data = dataWith('mode_multi_normal', 3, 'tactic', { tactic: ['map_m01_1', 'map_m02_1', 'allybuff_select_3'] });
  const h = makeMatch({ mode: 'coop', difficulty: 'NORMAL', humans: 2, seed: 63, data, registry: REG, fake: true });
  const m = h.m;
  h.start();
  h.setStage('act1autochess_m01');
  const sp = toDraft(h, 3);
  assert.ok(!sp.cards.some((c) => c.id === 'map_m02_1'), 'terrain cards only for the match stage');
  offerTactic(m, ['map_m01_1', 'allybuff_select_3']);
  const [a, b] = sp.order;
  draftPicks(h, { [a]: 'map_m01_1', [b]: 'allybuff_select_3' });
  const A = h.ps(a);
  const B = h.ps(b);
  const aliases = mapAliases(EFF('map_m01_1'));
  for (const k of Object.keys(aliases)) assert.equal(A.deviceOverrides[k], false, k);
  assert.equal(Object.keys(B.deviceOverrides).length, 0, 'the teammate keeps its crates');
  // an own crate tile (#0xx) becomes deployable for A only
  const crate = m.stage.devices.find((d) => d.alias === 'trap_1105_accrate#002');
  const [r, c] = crate.pos ?? [crate.row, crate.col];
  const id = chessOfTier(1).find((x) => DATA.chess[x].position !== 'RANGED') ?? chessOfTier(1)[0];
  const pa = give(m, A, id);
  assert.deepEqual(m.handle(a, { t: 'g.move', uid: pa.uid, to: { area: 'board', row: r, col: c } }), { ok: true }, 'deploy where the crate stood');
  const pb = give(m, B, id);
  assert.notDeepEqual(m.handle(b, { t: 'g.move', uid: pb.uid, to: { area: 'board', row: r, col: c } }), { ok: true }, 'still a crate for B');
  runTo(h, () => m.phase === 'ROUND_START' && m.round === 4);
  const input = FakeBattle.instances.find((f) => f.round === 3 && f.players.includes(a)).opts.players[0];
  const ref = input.playerEffects.find((e) => e.key === 'choice:map_m01_1');
  assert.ok(ref && Object.keys(aliases).every((k) => ref.params[k] === 0));
  // the real sim with only the EffectRef (devices.js reads its params)
  const hb = makeBattle({ stageId: 'act1autochess_m01', players: [{ ...input, deviceOverrides: undefined, units: [] }], autoFinish: false, timeLimit: 10 });
  hb.step();
  assert.equal(hb.b.allyUnits.filter((u) => u.kind === 'device' && u.alive && u.defId === 'trap_1105_accrate').length, 0, 'no crate left on A\'s field');
  const plain = makeBattle({ stageId: 'act1autochess_m01', autoFinish: false, timeLimit: 10 });
  plain.step();
  assert.ok(plain.b.allyUnits.some((u) => u.kind === 'device' && u.alive && u.defId === 'trap_1105_accrate'));
  matchInvariants(m);
  m.dispose();
});

